-- The countries Settings saved, if any, win: their names, dial codes and languages, and any
-- country they added.
SELECT DISTINCT ON (upper(e->>'code')) upper(e->>'code'), btrim(e->>'name'), coalesce(e->>'dial', ''), lower(coalesce(e->>'lang', 'en'))
FROM jsonb_array_elements(
  coalesce((SELECT "value" FROM "config_tables" WHERE "name" = 'countries' AND jsonb_typeof("value") = 'array'), '[]'::jsonb)
) e
WHERE upper(e->>'code') ~ '^[A-Z]{2}$' AND btrim(coalesce(e->>'name', '')) <> ''
ORDER BY upper(e->>'code')
ON CONFLICT ("code") DO UPDATE SET "name" = excluded."name", "dial" = excluded."dial", "lang" = excluded."lang";
--> statement-breakpoint
-- A record's country code, cleaned: upper case, the EU's UK and EL as ISO's GB and GR, empty as none.
UPDATE "contacts" SET "country" = NULLIF(CASE upper(btrim("country")) WHEN 'UK' THEN 'GB' WHEN 'EL' THEN 'GR' ELSE upper(btrim("country")) END, '');
--> statement-breakpoint
UPDATE "contact_addresses" SET "country" = NULLIF(CASE upper(btrim("country")) WHEN 'UK' THEN 'GB' WHEN 'EL' THEN 'GR' ELSE upper(btrim("country")) END, '');
--> statement-breakpoint
UPDATE "rate_items" SET "country" = NULLIF(CASE upper(btrim("country")) WHEN 'UK' THEN 'GB' WHEN 'EL' THEN 'GR' ELSE upper(btrim("country")) END, '');
--> statement-breakpoint
-- A code still unknown was a working country: it becomes a row, named by its code, to complete.
SELECT DISTINCT c, c FROM (
  SELECT "country" AS c FROM "contacts" UNION ALL SELECT "country" FROM "contact_addresses"
  UNION ALL SELECT "country" FROM "rate_items" UNION ALL SELECT "country" FROM "ports"
) x
WHERE c IS NOT NULL
ON CONFLICT ("code") DO NOTHING;
