-- Words as a search reads them: no accents, no case, letters and digits only.
CREATE FUNCTION pg_temp.ckey(v text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT btrim(regexp_replace(lower(translate(coalesce(v, ''),
    'ÀÁÂÃÄÅàáâãäåÇçĆćČčÈÉÊËèéêëĘęĚěÌÍÎÏìíîïİıÑñŃńŇňÒÓÔÕÖØòóôõöøŐőŘřŚśŠšŞşŢţŤťÙÚÛÜùúûüŰűŮůÝýÿŹźŻżŽžĞğŁłÆæŒœß',
    'AAAAAAaaaaaaCcCcCcEEEEeeeeEeEeIIIIiiiiIiNnNnNnOOOOOOooooooOoRrSsSsSsTtTtUUUUuuuuUuUuYyyZzZzZzGgLlAaOos')),
    '[^a-z0-9]+', ' ', 'g'))
$$;
--> statement-breakpoint
UPDATE "cities" SET "search_key" = pg_temp.ckey(concat_ws(' ', "name", array_to_string("aliases", ' '), "region"));
--> statement-breakpoint
-- Every name a city answers to, for the records' words to find it.
CREATE TEMP TABLE "city_keys" ON COMMIT DROP AS
SELECT c."id", c."country", pg_temp.ckey(k) AS "key", coalesce(c."population", 0) AS "pop"
FROM "cities" c, unnest(array_prepend(c."name", c."aliases")) k;
--> statement-breakpoint
CREATE INDEX ON "city_keys" ("country", "key");
--> statement-breakpoint
-- A city as a record typed it, without a trailing "(PT)": the biggest city of its country by that name.
CREATE FUNCTION pg_temp.city_of(cc text, v text) RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT k."id" FROM "city_keys" k
  WHERE k."country" = cc AND k."key" = pg_temp.ckey(regexp_replace(btrim(v), '\s*\([^)]*\)\s*$', ''))
  ORDER BY k."pop" DESC LIMIT 1
$$;
--> statement-breakpoint
UPDATE "contacts" SET "city_id" = pg_temp.city_of("country", "city")
WHERE "country" IS NOT NULL AND btrim(coalesce("city", '')) <> '';
--> statement-breakpoint
UPDATE "contact_addresses" SET "city_id" = pg_temp.city_of("country", "city")
WHERE "country" IS NOT NULL AND btrim(coalesce("city", '')) <> '';
