-- A city typed with no country has no list to be in: its words stay in the contact's note.
UPDATE "contacts" SET "note" = concat_ws(E'\n', "note", 'City before the city list: ' || btrim("city"))
WHERE "country" IS NULL AND btrim(coalesce("city", '')) <> '';
